import React from 'react';
import { ThemeLogo, Text, SizeEnum, ColorNameEnum, AlignEnum, WeightEnum } from '@getvim/atomic-ui';
import './index.less';

export interface AppsContainerHeaderProps {
  patientName: string;
  patientDateOfBirth: string;
  patientAge: string;
  insurerLogoUrl: string;
}

const AppsContainerHeader: React.FC<AppsContainerHeaderProps> = ({
  patientName,
  patientDateOfBirth,
  patientAge,
  insurerLogoUrl,
}) => (
  <header className="apps-container-header">
    <div className="header-top-section">
      <ThemeLogo />
      <Text
        text={patientName}
        size={SizeEnum['18px']}
        colorName={ColorNameEnum.ultraDark}
        align={AlignEnum.left}
        weight={WeightEnum.bold}
        className="patient-name"
      />
      <div className="patient-details">
        <Text size={SizeEnum['13px']} colorName={ColorNameEnum.ultraDark} className="patient-dob">
          {patientDateOfBirth}&nbsp;&nbsp;/&nbsp;&nbsp;{patientAge}
        </Text>
        {insurerLogoUrl && (
          <>
            &nbsp;&nbsp;/&nbsp;&nbsp;
            <img src={insurerLogoUrl} alt="Insurer logo" className="patient-insurer-logo" />
          </>
        )}
      </div>
    </div>
  </header>
);

export default AppsContainerHeader;
